def _write_tokens(chunks: Iterator[list[int]], target_tokens: int, destination: Path) -> int:
    with destination.open("wb") as handle:
        with tqdm(total=target_tokens, unit="tok", unit_scale=True, desc="caching tokens") as bar:
            return _write_stream(chunks, target_tokens, handle, bar)


def _write_stream(
    chunks: Iterator[list[int]], limit: int, handle: BinaryIO, bar: "tqdm[Never]"
) -> int:
    written = 0
    pending: list[int] = []
    for chunk in chunks:
        pending.extend(chunk)
        if len(pending) < CACHE_FLUSH_TOKENS:
            continue
        written += _flush(handle, pending, limit - written, bar)
        pending.clear()
        if written >= limit:
            return written
    if written < limit and pending:
        written += _flush(handle, pending, limit - written, bar)
    return written
